Absolutely — here’s a full little browser game you can play right now.

Copy this into a file called `cat-fish-game.html`, then open it in your browser.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <title>Cat Fish Catch</title>
  <style>
    body {
      margin: 0;
      background: linear-gradient(#8fd3ff, #dff6ff);
      font-family: Arial, sans-serif;
      overflow: hidden;
      text-align: center;
    }

    h1 {
      margin: 10px 0 0;
      color: #17415f;
    }

    #game {
      display: block;
      margin: 10px auto;
      background: linear-gradient(#9ee7ff, #f6fdff);
      border: 4px solid #17415f;
      border-radius: 12px;
    }

    #info {
      font-size: 18px;
      color: #17415f;
    }

    button {
      margin-top: 8px;
      padding: 10px 18px;
      border: none;
      border-radius: 8px;
      background: #ff9f43;
      color: white;
      font-size: 16px;
      cursor: pointer;
    }

    button:hover {
      background: #ff7f0e;
    }
  </style>
</head>
<body>
  <h1>🐱 Cat Fish Catch 🐟</h1>
  <div id="info">Move with ← → or A/D. Catch fish, avoid boots!</div>
  <canvas id="game" width="600" height="500"></canvas>
  <br />
  <button onclick="restartGame()">Restart</button>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    let keys = {};
    let score = 0;
    let lives = 3;
    let gameOver = false;
    let spawnTimer = 0;
    let fallingItems = [];

    const cat = {
      x: canvas.width / 2 - 35,
      y: canvas.height - 70,
      width: 70,
      height: 55,
      speed: 6
    };

    document.addEventListener("keydown", (e) => {
      keys[e.key.toLowerCase()] = true;
    });

    document.addEventListener("keyup", (e) => {
      keys[e.key.toLowerCase()] = false;
    });

    function drawCat() {
      const x = cat.x;
      const y = cat.y;

      // Body
      ctx.fillStyle = "#ffb347";
      ctx.beginPath();
      ctx.ellipse(x + 35, y + 35, 32, 22, 0, 0, Math.PI * 2);
      ctx.fill();

      // Head
      ctx.beginPath();
      ctx.arc(x + 35, y + 18, 24, 0, Math.PI * 2);
      ctx.fill();

      // Ears
      ctx.beginPath();
      ctx.moveTo(x + 15, y + 5);
      ctx.lineTo(x + 22, y - 15);
      ctx.lineTo(x + 30, y + 5);
      ctx.fill();

      ctx.beginPath();
      ctx.moveTo(x + 40, y + 5);
      ctx.lineTo(x + 48, y - 15);
      ctx.lineTo(x + 55, y + 5);
      ctx.fill();

      // Eyes
      ctx.fillStyle = "black";
      ctx.beginPath();
      ctx.arc(x + 26, y + 15, 3, 0, Math.PI * 2);
      ctx.arc(x + 44, y + 15, 3, 0, Math.PI * 2);
      ctx.fill();

      // Nose
      ctx.fillStyle = "#ff6b81";
      ctx.beginPath();
      ctx.arc(x + 35, y + 24, 3, 0, Math.PI * 2);
      ctx.fill();

      // Basket
      ctx.fillStyle = "#8b5a2b";
      ctx.fillRect(x + 8, y + 45, 54, 12);
      ctx.fillStyle = "#a66a35";
      ctx.fillRect(x + 13, y + 38, 44, 10);
    }

    function drawFish(item) {
      ctx.save();
      ctx.translate(item.x, item.y);

      ctx.fillStyle = "#2ec4ff";
      ctx.beginPath();
      ctx.ellipse(0, 0, 18, 9, 0, 0, Math.PI * 2);
      ctx.fill();

      ctx.beginPath();
      ctx.moveTo(-18, 0);
      ctx.lineTo(-32, -10);
      ctx.lineTo(-32, 10);
      ctx.closePath();
      ctx.fill();

      ctx.fillStyle = "white";
      ctx.beginPath();
      ctx.arc(9, -2, 3, 0, Math.PI * 2);
      ctx.fill();

      ctx.fillStyle = "black";
      ctx.beginPath();
      ctx.arc(10, -2, 1.5, 0, Math.PI * 2);
      ctx.fill();

      ctx.restore();
    }

    function drawBoot(item) {
      ctx.save();
      ctx.translate(item.x, item.y);

      ctx.fillStyle = "#5c4033";
      ctx.fillRect(-10, -20, 18, 30);
      ctx.fillRect(-10, 5, 35, 14);

      ctx.fillStyle = "#3b281f";
      ctx.fillRect(-12, 15, 40, 6);

      ctx.restore();
    }

    function spawnItem() {
      const isBoot = Math.random() < 0.2;

      fallingItems.push({
        x: Math.random() * (canvas.width - 60) + 30,
        y: -30,
        width: isBoot ? 40 : 45,
        height: isBoot ? 45 : 25,
        speed: Math.random() * 2 + 2 + score * 0.03,
        type: isBoot ? "boot" : "fish"
      });
    }

    function update() {
      if (gameOver) return;

      if (keys["arrowleft"] || keys["a"]) {
        cat.x -= cat.speed;
      }

      if (keys["arrowright"] || keys["d"]) {
        cat.x += cat.speed;
      }

      cat.x = Math.max(0, Math.min(canvas.width - cat.width, cat.x));

      spawnTimer++;
      if (spawnTimer > 45) {
        spawnItem();
        spawnTimer = 0;
      }

      for (let i = fallingItems.length - 1; i >= 0; i--) {
        const item = fallingItems[i];
        item.y += item.speed;

        const caught =
          item.x + item.width / 2 > cat.x &&
          item.x - item.width / 2 < cat.x + cat.width &&
          item.y + item.height / 2 > cat.y &&
          item.y - item.height / 2 < cat.y + cat.height;

        if (caught) {
          if (item.type === "fish") {
            score++;
          } else {
            lives--;
          }

          fallingItems.splice(i, 1);

          if (lives <= 0) {
            gameOver = true;
          }
        } else if (item.y > canvas.height + 50) {
          if (item.type === "fish") {
            lives--;
          }

          fallingItems.splice(i, 1);

          if (lives <= 0) {
            gameOver = true;
          }
        }
      }
    }

    function drawCloud(x, y) {
      ctx.fillStyle = "rgba(255, 255, 255, 0.85)";
      ctx.beginPath();
      ctx.arc(x, y, 18, 0, Math.PI * 2);
      ctx.arc(x + 20, y - 8, 22, 0, Math.PI * 2);
      ctx.arc(x + 45, y, 18, 0, Math.PI * 2);
      ctx.fillRect(x, y - 5, 45, 20);
      ctx.fill();
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      drawCloud(60, 60);
      drawCloud(350, 90);
      drawCloud(470, 45);

      fallingItems.forEach((item) => {
        if (item.type === "fish") {
          drawFish(item);
        } else {
          drawBoot(item);
        }
      });

      drawCat();

      ctx.fillStyle = "#17415f";
      ctx.font = "22px Arial";
      ctx.fillText("Score: " + score, 20, 35);
      ctx.fillText("Lives: " + "❤️".repeat(lives), 450, 35);

      if (gameOver) {
        ctx.fillStyle = "rgba(0, 0, 0, 0.55)";
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        ctx.fillStyle = "white";
        ctx.font = "42px Arial";
        ctx.fillText("Game Over!", 190, 220);

        ctx.font = "24px Arial";
        ctx.fillText("Final Score: " + score, 225, 260);
        ctx.fillText("Click Restart to play again", 165, 300);
      }
    }

    function gameLoop() {
      update();
      draw();
      requestAnimationFrame(gameLoop);
    }

    function restartGame() {
      score = 0;
      lives = 3;
      gameOver = false;
      fallingItems = [];
      cat.x = canvas.width / 2 - 35;
      spawnTimer = 0;
    }

    gameLoop();
  </script>
</body>
</html>
```

Controls:

- Move left: `←` or `A`
- Move right: `→` or `D`
- Catch fish: `+1 point`
- Miss a fish: lose a life
- Catch a boot: lose a life

It runs fully in the browser, no install needed.

