4. Click **Run** at the top.

Use the left and right arrow keys to move the cat. Catch 🐟, dodge 👢.

Yesss, nice 😄

To make the cat bigger and add a golden fish worth 5 points, replace everything in the JSFiddle HTML box with this upgraded version, then hit **Run** again:

```html
<canvas id="c" width="500" height="400"></canvas>

<script>
let c = document.getElementById("c");
let x = c.getContext("2d");

let cat = 205;
let fish = [];
let score = 0;
let lives = 3;
let keys = {};

document.onkeydown = e => keys[e.key] = true;
document.onkeyup = e => keys[e.key] = false;

function loop() {
  x.clearRect(0, 0, 500, 400);

  // sky
  x.fillStyle = "#9ee7ff";
  x.fillRect(0, 0, 500, 400);

  // grass
  x.fillStyle = "#78d66b";
  x.fillRect(0, 360, 500, 40);

  // move cat
  if (keys.ArrowLeft || keys.a) cat -= 6;
  if (keys.ArrowRight || keys.d) cat += 6;
  cat = Math.max(0, Math.min(410, cat));

  // spawn falling things
  if (Math.random() < 0.04) {
    let random = Math.random();

    fish.push({
      x: Math.random() * 460,
      y: -30,
      type: random < 0.15 ? "boot" : random < 0.30 ? "gold" : "fish"
    });
  }

  // draw and update fish
  for (let i = fish.length - 1; i >= 0; i--) {
    let f = fish[i];
    f.y += 3 + score * 0.025;

    x.font = "32px Arial";

    if (f.type === "boot") {
      x.fillText("👢", f.x, f.y);
    } else if (f.type === "gold") {
      x.fillText("🐠", f.x, f.y);
    } else {
      x.fillText("🐟", f.x, f.y);
    }

    // catching area
    if (f.y > 300 && f.y < 380 && f.x > cat - 25 && f.x < cat + 95) {
      if (f.type === "boot") {
        lives--;
      } else if (f.type === "gold") {
        score += 5;
      } else {
        score++;
      }

      fish.splice(i, 1);
    } else if (f.y > 420) {
      if (f.type !== "boot") {
        lives--;
      }

      fish.splice(i, 1);
    }
  }

  // bigger cat
  x.font = "75px Arial";
  x.fillText("🐱", cat, 365);

  // score and lives
  x.font = "20px Arial";
  x.fillStyle = "#123";
  x.fillText("Score: " + score, 15, 30);
  x.fillText("Lives: " + "❤️".repeat(lives), 350, 30);

  // instructions
  x.font = "16px Arial";
  x.fillText("Catch 🐟 = 1 point, 🐠 = 5 points, avoid 👢", 80, 390);

  if (lives <= 0) {
    x.fillStyle = "rgba(0,0,0,.6)";
    x.fillRect(0, 0, 500, 400);

    x.fillStyle = "white";
    x.font = "36px Arial";
    x.fillText("Game Over!", 150, 180);

    x.font = "22px Arial";
    x.fillText("Final Score: " + score, 175, 220);
    x.fillText("Refresh to play again", 155, 255);
    return;
  }

  requestAnimationFrame(loop);
}

loop();
</script>
```

The main changes are:

```js
x.font = "75px Arial";
x.fillText("🐱", cat, 365);
```

That makes the cat bigger.

And this part adds the golden fish:

```js
type: random < 0.15 ? "boot" : random < 0.30 ? "gold" : "fish"
```

Then this part gives it 5 points:

```js
} else if (f.type === "gold") {
  score += 5;
}
```

In the game, the golden fish is the orange `🐠`. It gives **5 points**.

YAY 32 points is solid 🐱🏆

Replace everything in the JSFiddle HTML box with this version and hit **Run**. It adds:

- 🌈 rainbow in the sky
- 🐶 falling dog
- Boots and dogs both make you lose a life
