Absolutely 😄 replace the whole HTML box with this version and hit **Run**. It adds a super fast mouse 🐭 that zips across the grass. Touch it with the cat to get **10 points**.

```html
<canvas id="c" width="500" height="400"></canvas>

<script>
let c = document.getElementById("c");
let x = c.getContext("2d");

let cat = 205;
let fish = [];
let mice = [];
let score = 0;
let lives = 3;
let keys = {};
let mouseTimer = 0;

document.onkeydown = e => keys[e.key] = true;
document.onkeyup = e => keys[e.key] = false;

function drawRainbow() {
  x.lineWidth = 10;

  x.strokeStyle = "red";
  x.beginPath();
  x.arc(250, 210, 170, Math.PI, 0);
  x.stroke();

  x.strokeStyle = "orange";
  x.beginPath();
  x.arc(250, 210, 155, Math.PI, 0);
  x.stroke();

  x.strokeStyle = "yellow";
  x.beginPath();
