  x.stroke();

  x.strokeStyle = "blue";
  x.beginPath();
  x.arc(250, 210, 110, Math.PI, 0);
  x.stroke();

  x.strokeStyle = "purple";
  x.beginPath();
  x.arc(250, 210, 95, Math.PI, 0);
  x.stroke();
}

function loop() {
  x.clearRect(0, 0, 500, 400);

  // sky
  x.fillStyle = "#9ee7ff";
  x.fillRect(0, 0, 500, 400);

  // rainbow
  drawRainbow();

  // grass
  x.fillStyle = "#78d66b";
  x.fillRect(0, 360, 500, 40);

  // move cat
  if (keys.ArrowLeft || keys.a) cat -= 6;
  if (keys.ArrowRight || keys.d) cat += 6;
  cat = Math.max(0, Math.min(410, cat));

  // spawn falling things
  if (Math.random() < 0.045) {
    let random = Math.random();

    fish.push({
      x: Math.random() * 460,
      y: -30,
      type:
        random < 0.12 ? "boot" :
        random < 0.24 ? "dog" :
        random < 0.38 ? "gold" :
        "fish"
    });
  }

  // spawn super fast mouse sometimes
  mouseTimer++;

  if (mouseTimer > 180 && Math.random() < 0.03) {
    let fromLeft = Math.random() < 0.5;

    mice.push({
      x: fromLeft ? -40 : 540,
      y: 350,
      speed: fromLeft ? 10 : -10
    });

    mouseTimer = 0;
  }

  // draw and update falling things
  for (let i = fish.length - 1; i >= 0; i--) {
    let f = fish[i];
    f.y += 3 + score * 0.025;

    x.font = "32px Arial";

    if (f.type === "boot") {
      x.fillText("👢", f.x, f.y);
    } else if (f.type === "dog") {
      x.fillText("🐶", f.x, f.y);
    } else if (f.type === "gold") {
      x.fillText("🐠", f.x, f.y);
    } else {
      x.fillText("🐟", f.x, f.y);
    }

    // catching / crashing area
    if (f.y > 300 && f.y < 380 && f.x > cat - 25 && f.x < cat + 95) {
      if (f.type === "boot" || f.type === "dog") {
        lives--;
      } else if (f.type === "gold") {
        score += 5;
      } else {
        score++;
      }

      fish.splice(i, 1);
    } else if (f.y > 420) {
      if (f.type === "fish" || f.type === "gold") {
        lives--;
      }

      fish.splice(i, 1);
    }
  }

  // draw and update mice
  for (let i = mice.length - 1; i >= 0; i--) {
    let m = mice[i];
    m.x += m.speed;

    x.font = "30px Arial";
    x.fillText("🐭", m.x, m.y);

    // catch mouse with cat
    if (m.x > cat - 20 && m.x < cat + 90) {
      score += 10;
      mice.splice(i, 1);
    } else if (m.x < -80 || m.x > 580) {
      mice.splice(i, 1);
    }
  }

  // big cat
  x.font = "75px Arial";
  x.fillText("🐱", cat, 365);

  // score and lives
  x.font = "20px Arial";
  x.fillStyle = "#123";
  x.fillText("Score: " + score, 15, 30);
  x.fillText("Lives: " + "❤️".repeat(lives), 350, 30);

  // instructions
  x.font = "15px Arial";
  x.fillText("Catch 🐟 🐠 🐭. Dodge 👢 and 🐶!", 105, 390);

  if (lives <= 0) {
    x.fillStyle = "rgba(0,0,0,.6)";
    x.fillRect(0, 0, 500, 400);

    x.fillStyle = "white";
    x.font = "36px Arial";
    x.fillText("Game Over!", 150, 180);

    x.font = "22px Arial";
    x.fillText("Final Score: " + score, 175, 220);
