  function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    fish.forEach(drawFish);
    drawGround();
    drawOrangeCat();

    ctx.fillStyle = "#222";
    ctx.font = "20px Arial";
    ctx.fillText("Score: " + score, 20, 30);
    ctx.fillText("Missed: " + missed + "/5", 20, 58);

    ctx.fillStyle = "#b85c00";
    ctx.font = "16px Arial";
    ctx.fillText("🐠 Goldfish = 5 points", 390, 30);
    ctx.fillText("↑ or Space = Jump", 390, 55);

    if (gameOver) {
      ctx.fillStyle = "rgba(0,0,0,0.65)";
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      ctx.fillStyle = "white";
      ctx.font = "40px Arial";
      ctx.fillText("Game Over!", 190, 170);

      ctx.font = "24px Arial";
      ctx.fillText("Score: " + score, 255, 215);
      ctx.fillText("Press Enter to Restart", 178, 255);
    }
  }

  function loop() {
    if (!gameOver) update();
    draw();
    requestAnimationFrame(loop);
  }

  loop();
</script>
```

I also changed restart to **Enter**, because Space is now for jumping. Tiny game-design wisdom: never make the cat jump and reboot the universe with the same button.

