</style>

<script>
  const canvas = document.getElementById("game");
  const ctx = canvas.getContext("2d");

  const groundY = canvas.height - 70;

  const cat = {
    x: canvas.width / 2 - 35,
    y: groundY,
    width: 80,
    height: 60,
    speed: 7,
    velocityY: 0,
    jumpPower: -13,
    gravity: 0.65,
    onGround: true
  };

  let fallingThings = [];
  let score = 0;
  let missed = 0;
  let gameOver = false;
  let leftPressed = false;
  let rightPressed = false;
  let spawnTimer = 0;
  let message = "";
  let messageTimer = 0;

  document.addEventListener("keydown", (e) => {
    if (e.key === "ArrowLeft") leftPressed = true;
    if (e.key === "ArrowRight") rightPressed = true;

    if ((e.key === "ArrowUp" || e.key === " ") && cat.onGround && !gameOver) {
      cat.velocityY = cat.jumpPower;
      cat.onGround = false;
    }

    if (e.key === "Enter" && gameOver) {
      restartGame();
    }
  });

  document.addEventListener("keyup", (e) => {
    if (e.key === "ArrowLeft") leftPressed = false;
    if (e.key === "ArrowRight") rightPressed = false;
  });

  function restartGame() {
    fallingThings = [];
    score = 0;
    missed = 0;
    gameOver = false;
    message = "";
    messageTimer = 0;
    cat.x = canvas.width / 2 - 35;
    cat.y = groundY;
    cat.velocityY = 0;
    cat.onGround = true;
  }

  function spawnThing() {
    const random = Math.random();
    let type;

    if (random < 0.13) {
      type = "gold";
    } else if (random < 0.27) {
      type = "shoe";
    } else if (random < 0.37) {
      type = "bomb";
    } else {
      type = "normal";
    }

    let speed = 2 + Math.random() * 3;

    if (type === "gold") speed = 3.5 + Math.random() * 2;
    if (type === "shoe") speed = 2.5 + Math.random() * 3;
    if (type === "bomb") speed = 3 + Math.random() * 3;

    fallingThings.push({
      x: Math.random() * (canvas.width - 40),
      y: -30,
      speed: speed,
      type: type
    });
  }

  function getPoints(type) {
    if (type === "gold") return 5;
    if (type === "shoe") return -3;
    if (type === "bomb") return -10;
    return 1;
  }

  function showMessage(text) {
    message = text;
    messageTimer = 45;
  }

  function drawOrangeCat() {
    const x = cat.x;
    const y = cat.y;

    // Shadow
    ctx.fillStyle = "rgba(0, 0, 0, 0.18)";
    ctx.beginPath();
    ctx.ellipse(x + 40, groundY + 64, 34, 7, 0, 0, Math.PI * 2);
    ctx.fill();

    // Body
    ctx.fillStyle = "#f28c28";
    ctx.beginPath();
    ctx.ellipse(x + 40, y + 38, 34, 24, 0, 0, Math.PI * 2);
    ctx.fill();

    // Head
    ctx.beginPath();
    ctx.arc(x + 40, y + 18, 24, 0, Math.PI * 2);
    ctx.fill();

    // Ears
    ctx.beginPath();
    ctx.moveTo(x + 20, y + 6);
    ctx.lineTo(x + 27, y - 18);
    ctx.lineTo(x + 36, y + 4);
    ctx.fill();

    ctx.beginPath();
    ctx.moveTo(x + 44, y + 4);
    ctx.lineTo(x + 53, y - 18);
    ctx.lineTo(x + 60, y + 6);
    ctx.fill();

    // Stripes
    ctx.strokeStyle = "#b85c00";
    ctx.lineWidth = 3;

    ctx.beginPath();
    ctx.moveTo(x + 28, y + 11);
    ctx.lineTo(x + 20, y + 5);
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(x + 40, y + 8);
    ctx.lineTo(x + 40, y - 2);
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(x + 52, y + 11);
    ctx.lineTo(x + 60, y + 5);
    ctx.stroke();

    // Eyes
    ctx.fillStyle = "#222";
    ctx.beginPath();
    ctx.arc(x + 31, y + 18, 3, 0, Math.PI * 2);
    ctx.arc(x + 49, y + 18, 3, 0, Math.PI * 2);
    ctx.fill();

    // Nose
    ctx.fillStyle = "#ffbfd1";
    ctx.beginPath();
    ctx.arc(x + 40, y + 27, 3, 0, Math.PI * 2);
    ctx.fill();

    // Tail
    ctx.strokeStyle = "#f28c28";
    ctx.lineWidth = 10;
    ctx.beginPath();
    ctx.arc(x + 76, y + 34, 18, Math.PI * 0.7, Math.PI * 1.8);
    ctx.stroke();

    // Catching basket/paws
    ctx.fillStyle = "#8b5a2b";
    ctx.fillRect(x + 12, y + 55, cat.width - 24, 8);
  }

  function drawThing(thing) {
    if (thing.type === "gold") {
      ctx.font = "32px serif";
      ctx.fillText("🐠", thing.x, thing.y);

      ctx.fillStyle = "#ffd700";
      ctx.font = "16px serif";
      ctx.fillText("✦", thing.x - 8, thing.y - 8);
      ctx.fillText("✦", thing.x + 28, thing.y + 4);
    }

    if (thing.type === "normal") {
      ctx.font = "30px serif";
      ctx.fillText("🐟", thing.x, thing.y);
    }

    if (thing.type === "shoe") {
      ctx.font = "31px serif";
      ctx.fillText("👟", thing.x, thing.y);

      ctx.fillStyle = "#6b6b6b";
      ctx.font = "14px Arial";
      ctx.fillText("stinky", thing.x - 3, thing.y - 28);
    }

    if (thing.type === "bomb") {
      ctx.font = "31px serif";
      ctx.fillText("💣", thing.x, thing.y);

      ctx.fillStyle = "#ff3333";
      ctx.font = "15px Arial";
      ctx.fillText("NO!", thing.x + 2, thing.y - 28);
    }
  }

  function updateCat() {
    if (leftPressed) cat.x -= cat.speed;
    if (rightPressed) cat.x += cat.speed;

    if (cat.x < 0) cat.x = 0;
    if (cat.x + cat.width > canvas.width) {
      cat.x = canvas.width - cat.width;
    }

    cat.y += cat.velocityY;
    cat.velocityY += cat.gravity;

    if (cat.y >= groundY) {
      cat.y = groundY;
      cat.velocityY = 0;
      cat.onGround = true;
    }
  }

  function updateThings() {
    for (let i = fallingThings.length - 1; i >= 0; i--) {
      const thing = fallingThings[i];
      thing.y += thing.speed;

      const caught =
        thing.x + 30 > cat.x &&
        thing.x < cat.x + cat.width &&
        thing.y + 25 > cat.y &&
        thing.y < cat.y + cat.height;

      if (caught) {
        const points = getPoints(thing.type);
        score += points;

        if (score < 0) score = 0;

        if (thing.type === "gold") showMessage("+5 GOLD!");
        if (thing.type === "normal") showMessage("+1 fish!");
        if (thing.type === "shoe") showMessage("-3 STINKY SHOE!");
        if (thing.type === "bomb") showMessage("BOOM! -10!");

        fallingThings.splice(i, 1);
      } else if (thing.y > canvas.height) {
        if (thing.type === "normal" || thing.type === "gold") {
          missed++;
        }

        fallingThings.splice(i, 1);
      }
    }

    if (missed >= 5) gameOver = true;
  }

  function update() {
    updateCat();

    spawnTimer++;
    if (spawnTimer > Math.max(22, 65 - score)) {
      spawnThing();
      spawnTimer = 0;
    }

    updateThings();

    if (messageTimer > 0) {
      messageTimer--;
    } else {
      message = "";
    }
  }

  function drawGround() {
    ctx.fillStyle = "#74c365";
    ctx.fillRect(0, canvas.height - 12, canvas.width, 12);
  }

  function drawScoreboard() {
    ctx.fillStyle = "#222";
    ctx.font = "20px Arial";
    ctx.fillText("Score: " + score, 20, 30);
    ctx.fillText("Missed fish: " + missed + "/5", 20, 58);

    ctx.fillStyle = "#b85c00";
    ctx.font = "15px Arial";
    ctx.fillText("🐟 +1   🐠 +5", 390, 28);
    ctx.fillText("👟 -3   💣 -10", 390, 52);
    ctx.fillText("↑ or Space = Jump", 390, 76);
  }

  function drawMessage() {
    if (message !== "") {
      ctx.fillStyle = message.includes("-") || message.includes("BOOM") ? "#cc0000" : "#008a22";
      ctx.font = "28px Arial";
      ctx.fillText(message, 210, 110);
    }
  }

  function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    fallingThings.forEach(drawThing);
    drawGround();
    drawOrangeCat();
    drawScoreboard();
    drawMessage();

    if (gameOver) {
      ctx.fillStyle = "rgba(0,0,0,0.65)";
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      ctx.fillStyle = "white";
      ctx.font = "40px Arial";
      ctx.fillText("Game Over!", 190, 170);

      ctx.font = "24px Arial";
      ctx.fillText("Score: " + score, 255, 215);
      ctx.fillText("Press Enter to Restart", 178, 255);
    }
  }

  function loop() {
    if (!gameOver) update();
    draw();
    requestAnimationFrame(loop);
  }

  loop();
</script>
