      ctx.moveTo(15, 4);
      ctx.lineTo(23, -17);
      ctx.lineTo(32, 4);
      ctx.fill();

      ctx.beginPath();
      ctx.moveTo(38, 4);
      ctx.lineTo(48, -17);
