      ctx.fillStyle = "#8b5a2b";
      ctx.fillRect(8, 45, 54, 12);
      ctx.strokeStyle = "#5b3519";
      ctx.lineWidth = 3;
      ctx.strokeRect(8, 45, 54, 12);

