    }

    function spawnObject() {
      const isBoot = Math.random() < 0.18;

      const obj = {
        x: Math.random() * (canvas.width - 60) + 30,
        y: -30,
        speed: Math.random() * 2 + 2 + difficulty,
        rotation: Math.random() * Math.PI,
        spin: Math.random() * 0.08 - 0.04
      };

      if (isBoot) {
        boots.push(obj);
      } else {
        fish.push(obj);
      }
    }

    function updateCat() {
      if (keys["arrowleft"] || keys["a"]) {
        cat.x -= cat.speed;
      }

      if (keys["arrowright"] || keys["d"]) {
        cat.x += cat.speed;
      }

      cat.x = Math.max(0, Math.min(canvas.width - cat.width, cat.x));
