        obj.x > cat.x &&
        obj.x < cat.x + cat.width &&
        obj.y > cat.y &&
        obj.y < cat.y + cat.height
      );
    }

    function updateObjects() {
      for (let i = fish.length - 1; i >= 0; i--) {
        fish[i].y += fish[i].speed;
        fish[i].rotation += fish[i].spin;

        if (isCaught(fish[i])) {
          score++;
          fish.splice(i, 1);

          if (score % 10 === 0) {
