      for (let i = boots.length - 1; i >= 0; i--) {
        boots[i].y += boots[i].speed;
        boots[i].rotation += boots[i].spin;

        if (isCaught(boots[i])) {
          lives--;
          boots.splice(i, 1);

          if (lives <= 0) {
            gameOver = true;
          }
        } else if (boots[i].y > canvas.height + 40) {
          boots.splice(i, 1);
        }
      }
    }

    function drawGameOver() {
      ctx.fillStyle = "rgba(0, 0, 0, 0.65)";
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      ctx.fillStyle = "white";
      ctx.textAlign = "center";
      ctx.font = "42px Arial";
      ctx.fillText("Game Over", canvas.width / 2, canvas.height / 2 - 40);

      ctx.font = "24px Arial";
      ctx.fillText("Final Score: " + score, canvas.width / 2, canvas.height / 2 + 5);

      ctx.font = "20px Arial";
      ctx.fillText("Press R to restart", canvas.width / 2, canvas.height / 2 + 45);

      ctx.textAlign = "left";
    }

    function restartGame() {
      fish = [];
      boots = [];
      score = 0;
      lives = 3;
      difficulty = 1;
      spawnTimer = 0;
      cat.x = canvas.width / 2 - cat.width / 2;
      gameOver = false;
    }

    function gameLoop() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // Ground
      ctx.fillStyle = "#7ec850";
      ctx.fillRect(0, canvas.height - 25, canvas.width, 25);

      if (!gameOver) {
        updateCat();

        spawnTimer++;
        if (spawnTimer > Math.max(18, 45 - difficulty * 4)) {
          spawnObject();
          spawnTimer = 0;
        }

        updateObjects();
      }

      fish.forEach(drawFish);
      boots.forEach(drawBoot);
      drawCat();
      drawHUD();

      if (gameOver) {
        drawGameOver();
      }

      requestAnimationFrame(gameLoop);
    }

    gameLoop();
  </script>
